SELECT jsonb_build_object('capturado_em',transaction_timestamp(),'read_only',current_setting('transaction_read_only'),
 'objects',(SELECT jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'size',pg_total_relation_size(c.oid),'acl',c.relacl,'reader_select',has_table_privilege('estudo_reader',c.oid,'SELECT'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='estudo' AND c.relname IN('fat_perfil_br_2026_20261109','fat_perfil_br_2026_20261109_audit','vwbi_perfil_br_2026_20261109','vw_resultados_2026_20261109','vwbi_perfil_br_2026','vw_resultados_2026')),
 'audit',(SELECT to_jsonb(a)-'views_before' FROM estudo.fat_perfil_br_2026_20261109_audit a),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',f.key,'expected',f.value,'actual',md5(pg_get_functiondef(to_regprocedure('public.'||f.key))),'matches',f.value=md5(pg_get_functiondef(to_regprocedure('public.'||f.key))))) FROM estudo.fat_perfil_br_2026_20261109_audit a CROSS JOIN LATERAL jsonb_each_text(a.function_contract) f),
 'view_hashes',(SELECT jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'md5',md5(pg_get_viewdef(c.oid,true)),'definition',pg_get_viewdef(c.oid,true))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='v' AND ((n.nspname='estudo' AND c.relname IN('vwbi_perfil_br_2026','vw_resultados_2026','vwbi_perfil_br_2026_20261109','vw_resultados_2026_20261109','vw_resultados_comparativo_2025_2026')) OR c.oid='public.vwbi_fat_perfil_br_2026'::regclass)),
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'n',a.n)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN LATERAL(SELECT count(*) AS n FROM pg_attribute WHERE attrelid=c.oid AND attnum>0 AND NOT attisdropped)a ON true WHERE n.nspname='estudo' AND c.relname IN('fat_perfil_br_2026_20261109','vwbi_perfil_br_2026_20261109','vw_resultados_2026_20261109','vwbi_perfil_br_2026','vw_resultados_2026')),
 'view_dependencies',(SELECT jsonb_agg(DISTINCT jsonb_build_object('view',v.oid::regclass::text,'source',c.oid::regclass::text)) FROM pg_rewrite r JOIN pg_class v ON v.oid=r.ev_class JOIN pg_namespace vn ON vn.oid=v.relnamespace JOIN pg_depend d ON d.objid=r.oid AND d.classid='pg_rewrite'::regclass AND d.refclassid='pg_class'::regclass JOIN pg_class c ON c.oid=d.refobjid WHERE vn.nspname='estudo' AND v.relname IN('vwbi_perfil_br_2026','vw_resultados_2026','vwbi_perfil_br_2026_20261109','vw_resultados_2026_20261109') AND c.oid<>v.oid),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',i.indexrelid::regclass::text,'unique',i.indisunique,'valid',i.indisvalid,'definition',pg_get_indexdef(i.indexrelid))) FROM pg_index i WHERE i.indrelid='estudo.fat_perfil_br_2026_20261109'::regclass)
 )::text AS payload